"""Fixed-width EXPORT_ACCT record formatter for Meridian CRM 4.2."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


def _value(row: dict, key: str) -> Any:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: Any, width: int) -> str:
    text = str(value)
    return text[:width].ljust(width)


def _cents(value: Any) -> int:
    text = str(value)
    if text.strip() == "":
        text = "0"

    try:
        amount = Decimal(text)
        if not amount.is_finite():
            raise ValueError("ANN_REV must be a finite decimal value")
        return int((amount * Decimal(100)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError) as exc:
        raise ValueError(f"invalid ANN_REV value: {value!r}") from exc


def _zpad(number: int, width: int) -> str:
    if number < 0:
        result = "-" + str(abs(number)).zfill(width - 1)
    else:
        result = str(number).zfill(width)

    if len(result) > width:
        raise ValueError(f"numeric value does not fit in {width} characters")
    return result


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT record without a terminator."""
    cred_hold_value = _value(row, "CRED_HOLD")
    cred_hold_text = str(cred_hold_value)
    cred_hold = "N" if cred_hold_text.strip() == "" else cred_hold_text

    create_dt_value = _value(row, "CREATE_DT")
    create_dt_text = str(create_dt_value)
    create_dt = "00000000" if create_dt_text.strip() == "" else create_dt_text

    if len(cred_hold) != 1:
        raise ValueError("CRED_HOLD must be one character")
    if len(create_dt) != 8:
        raise ValueError("CREATE_DT must be an 8-character YYYYMMDD value")

    record = (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _zpad(_cents(_value(row, "ANN_REV")), 15)
        + cred_hold
        + create_dt
    )

    if len(record) != 77:
        raise AssertionError("EXPORT_ACCT record must be exactly 77 characters")
    return record
